print(first_truthy(None, None, None))

items.solution_code:
def first_truthy(a, b, c):
    return next((x for x in (a, b, c) if x), None)

print(first_truthy(0, 'yes', False))
print(first_truthy(0, 0, 0))
print(first_truthy('', [], {}))
print(first_truthy(None, None, None))

